// A_World/VnVoicePack.cs — Vietnamese voice-pack loader (Resources-backed).
// Clips live in Assets/A_World/Resources/VietnameseVoice/<key>.mp3, generated by
// tools/pregen_vn_voice.ps1 (ONLINE TTS via the project worker — NOT human recordings;
// see PROVENANCE.txt in the same folder). Keys are pinned == runtime lookups.
// Honest contract: returns null when a clip is missing — callers must fall back to a
// text prompt, never pretend audio played.
using System.Collections.Generic;
using UnityEngine;

public static class VnVoicePack {
  static readonly Dictionary<string, AudioClip> _cache = new Dictionary<string, AudioClip>();

  public static AudioClip Get(string key) {
    if (string.IsNullOrEmpty(key)) return null;
    AudioClip c;
    if (_cache.TryGetValue(key, out c)) return c;
    c = Resources.Load<AudioClip>("VietnameseVoice/" + key);
    _cache[key] = c;
    return c;
  }

  public static void ClearCache() { _cache.Clear(); }
}
